style.css:
/* Targets the main vertical navigation sidebar and top brand area */
header, 
nav, 
[class*="sidebar"], 
[class*="nav"], 
div[style*="background-color: yellow"],
div[style*="background: yellow"] {
  background-color: #ffb6c1 !important; /* Light pink */
}

/* If the yellow is applied via specific element types on the left menu */
aside, 
section {
  background-color: #ffb6c1 !important;
}
